/*
 * dowel theme - the token vocabulary every product of the lacodda line shares.
 *
 * The vocabulary comes from the products themselves: kilna and kasl-server
 * already ship the same token names (bg / raise / soft / line / text / dim /
 * accent / good / warn / bad / info) and differ only in values. That is the
 * contract this file freezes. Names are the mockup's own words rather than
 * stock component-library names, so a screen can be checked against a mockup
 * in the mockup's words.
 *
 * Two things are parametric, and everything else is derived from them:
 *
 *   --accent-base   the product's hue from the brand-line registry
 *   --neutral-base  the hue the greys are tinted with (the accent, by default)
 *
 * Tinting the neutrals is not decoration - it is what the two live products do
 * by hand: kilna's greys lean magenta, kasl-server's lean gold. Here that lean
 * is one declaration instead of thirty hand-picked hex values.
 *
 * Soft variants are mixed from their own base with `color-mix`, so a product
 * that overrides `--accent-base` gets a matching `--accent-soft` for free and
 * cannot pick one that disagrees with it.
 *
 * Theme selection: no class on the root element follows the operating system,
 * an explicit `light` or `dark` class pins the theme. Components never use
 * `dark:` utilities - every colour goes through a token, and the theme swaps
 * the token underneath.
 */

:root {
  /* The two parameters. `--accent-base` is overridden per product by an accent
   * file; `--neutral-base` follows it unless a product says otherwise. */
  --accent-base: #e8862d;
  --neutral-base: var(--accent-base);

  /* Ink and ground of the dark theme, before the neutral tint is mixed in.
   * Kept as their own tokens so the tint amount is the only thing that
   * changes when a product wants greyer or warmer chrome. */
  --ground: #131316;
  --ink: #ece9ef;

  /* How much of `--neutral-base` bleeds into the greys. The live products sit
   * at roughly this much: enough that the chrome belongs to the product,
   * little enough that it still reads as grey. */
  --neutral-tint: 6%;
  --neutral-tint-strong: 9%;

  color-scheme: dark;

  --bg: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ground));
  --raise: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), #1c1c21);

  /* Surfaces that lift by translucency rather than by their own colour: they
   * must work over `--bg` and over `--raise` alike. */
  --soft: rgb(255 255 255 / 0.045);
  --softer: rgb(255 255 255 / 0.025);
  --line: rgb(255 255 255 / 0.08);
  --line-2: rgb(255 255 255 / 0.15);

  --text: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ink));
  --dim: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #a7a2ad);
  --faint: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #6e6a76);

  --accent: var(--accent-base);
  /* The hover/active partner: lighter on dark, where the ground is what the
   * accent has to separate from. */
  --accent-2: color-mix(in oklab, white 22%, var(--accent-base));
  --accent-soft: color-mix(in oklab, var(--accent-base) 16%, transparent);

  /* Status hues are the line's own and do not follow the product accent: a
   * green that shifted per product would stop meaning "good". Meaning never
   * rests on colour alone - a badge carries an icon and a word - so these
   * exist for emphasis, not as the message. */
  --good: #45d18f;
  --warn: #e8b13f;
  --bad: #ef6a6a;
  --info: #4cc4e0;
  --good-soft: color-mix(in oklab, var(--good) 14%, transparent);
  --warn-soft: color-mix(in oklab, var(--warn) 14%, transparent);
  --bad-soft: color-mix(in oklab, var(--bad) 14%, transparent);
  --info-soft: color-mix(in oklab, var(--info) 15%, transparent);

  /* Elevation, three steps. The products had one shadow and used it for
   * everything that leaves the flow - a toast, a dropdown and a modal all
   * floated by the same amount, so a modal never felt further away than the
   * menu it covered. `raise` keeps its original value, so nothing shifts under
   * the products already using it; the other two are the steps either side. */
  --shadow-lift: 0 2px 8px rgb(0 0 0 / 0.3);
  --shadow-raise: 0 10px 34px rgb(0 0 0 / 0.45);
  --shadow-float: 0 24px 60px rgb(0 0 0 / 0.55);
}

/*
 * Light theme, twice: once for the operating system's preference, once for the
 * explicit `light` class. The declarations are identical - only the selector
 * differs - so that a product can pin a theme against the system setting.
 */
@media (prefers-color-scheme: light) {
  :root:not(.dark) {
    color-scheme: light;

    --ground: #f6f5f7;
    --ink: #232027;

    --bg: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ground));
    --raise: #ffffff;

    /* Tinted, and translucent - which took two goes to get right.
     *
     * `color-mix` mixes the alpha along with the colour, so mixing 60% of an
     * opaque accent into a 5%-opaque grey gives a surface 62% opaque: twelve
     * times denser than the hairline it was meant to be. It went unnoticed for
     * ten versions because `bg-soft` was only ever used for a hover, where a
     * flash of colour reads as feedback rather than as a mistake. The first
     * component to sit on it permanently - Alert - made it obvious.
     *
     * `oklch(from … / alpha)` keeps the alpha out of the mix: the hue comes
     * from the tinted colour, the transparency is stated. */
    --soft: oklch(from color-mix(in oklab, var(--neutral-base) 45%, #181420) l c h / 0.05);
    --softer: oklch(from color-mix(in oklab, var(--neutral-base) 45%, #181420) l c h / 0.03);
    --line: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.11);
    --line-2: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.2);

    --text: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ink));
    --dim: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #63606b);
    --faint: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #8a8692);

    /* On a light ground the accent has to darken to stay legible as text and
     * as a fill. It darkens *to* a lightness rather than *by* an amount: how
     * far a hue has to travel depends on where it starts, and a fixed step
     * that suits magenta leaves lime and gold short. Pinning the lightness and
     * keeping the hue and chroma clears 5:1 for every accent in the line. */
    --accent: oklch(from var(--accent-base) 0.5 c h);
    --accent-2: oklch(from var(--accent-base) 0.4 c h);
    --accent-soft: color-mix(in oklab, var(--accent-base) 12%, transparent);

    --good: #0c8554;
    --warn: #9a6b0c;
    --bad: #c93b3b;
    --info: #0d7f9c;
    --good-soft: color-mix(in oklab, var(--good) 12%, transparent);
    --warn-soft: color-mix(in oklab, var(--warn) 14%, transparent);
    --bad-soft: color-mix(in oklab, var(--bad) 12%, transparent);
    --info-soft: color-mix(in oklab, var(--info) 11%, transparent);

    --shadow-lift: 0 2px 8px rgb(30 24 38 / 0.08);
    --shadow-raise: 0 10px 30px rgb(30 24 38 / 0.14);
    --shadow-float: 0 24px 60px rgb(30 24 38 / 0.18);
  }
}

:root.light {
  color-scheme: light;

  --ground: #f6f5f7;
  --ink: #232027;

  --bg: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ground));
  --raise: #ffffff;

  /* The same surfaces as above; see the note there. */
  --soft: oklch(from color-mix(in oklab, var(--neutral-base) 45%, #181420) l c h / 0.05);
  --softer: oklch(from color-mix(in oklab, var(--neutral-base) 45%, #181420) l c h / 0.03);
  --line: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.11);
  --line-2: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.2);

  --text: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ink));
  --dim: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #63606b);
  --faint: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #8a8692);

  /* Darkened to a lightness, not by an amount - see the note above. */
  --accent: oklch(from var(--accent-base) 0.5 c h);
  --accent-2: oklch(from var(--accent-base) 0.4 c h);
  --accent-soft: color-mix(in oklab, var(--accent-base) 12%, transparent);

  --good: #0c8554;
  --warn: #9a6b0c;
  --bad: #c93b3b;
  --info: #0d7f9c;
  --good-soft: color-mix(in oklab, var(--good) 12%, transparent);
  --warn-soft: color-mix(in oklab, var(--warn) 14%, transparent);
  --bad-soft: color-mix(in oklab, var(--bad) 12%, transparent);
  --info-soft: color-mix(in oklab, var(--info) 11%, transparent);

  --shadow-lift: 0 2px 8px rgb(30 24 38 / 0.08);
  --shadow-raise: 0 10px 30px rgb(30 24 38 / 0.14);
  --shadow-float: 0 24px 60px rgb(30 24 38 / 0.18);
}

/*
 * `--on-accent` - what sits on top of an accent fill.
 *
 * A light accent (gold, lime, amber) needs dark glyphs; a dark one needs
 * white. The live products picked this by hand and wrote the answer into the
 * theme; here the theme works it out, by the same rule the brand-line S tile
 * uses.
 *
 * `contrast-color()` is the direct way to say it and is used where supported.
 * The fallback covers browsers that lack it. Relative colour syntax exposes
 * the accent's own lightness as `l`; `clamp()` turns that into a hard switch,
 * because the multiplication drives the middle term far past either bound
 * everywhere except within a hair of the threshold. Below it the accent is
 * dark and the result is 1 (white); above it, 0 (black). Chroma is dropped to
 * zero, so what comes out is neutral rather than a tinted grey.
 *
 * The threshold is 0.58, and it is deliberately far below the midpoint an eye
 * would guess. Contrast is not symmetric about it: a mid-lightness colour is
 * still much closer to white than to black in luminance, so black wins well
 * before the colour looks light. Checked against all fourteen accents of the
 * line - every one of them reads better with dark glyphs, the closest being
 * cobalt at 4.86:1 against 4.32:1 for white. A higher threshold is what puts
 * white text on magenta at 3.6:1, which is the defect this rule exists to
 * prevent.
 */
:root {
  --on-accent: oklch(from var(--accent) clamp(0, (0.58 - l) * 1000, 1) 0 0);

  /*
   * The same question for the status fills, and it has to be asked separately:
   * `--on-accent` is derived from the accent, so using it on a `--warn` fill
   * is only ever right by coincidence. The line's first consumer did exactly
   * that - a count on a yellow badge, drawn in white at 1.95:1 - and it read
   * as correct for as long as the product happened to pin white.
   *
   * The status hues do not follow the product accent, so these four are the
   * same for every product; they are still derived rather than written down,
   * because the status colours themselves change between the themes.
   */
  --on-good: oklch(from var(--good) clamp(0, (0.58 - l) * 1000, 1) 0 0);
  --on-warn: oklch(from var(--warn) clamp(0, (0.58 - l) * 1000, 1) 0 0);
  --on-bad: oklch(from var(--bad) clamp(0, (0.58 - l) * 1000, 1) 0 0);
  --on-info: oklch(from var(--info) clamp(0, (0.58 - l) * 1000, 1) 0 0);
}

@supports (color: contrast-color(red)) {
  :root {
    --on-accent: contrast-color(var(--accent));
    --on-good: contrast-color(var(--good));
    --on-warn: contrast-color(var(--warn));
    --on-bad: contrast-color(var(--bad));
    --on-info: contrast-color(var(--info));
  }
}

/*
 * The Tailwind 4 surface. `--color-*: initial` drops the stock palette on
 * purpose: a raw `bg-zinc-800` in a product should not compile, because the
 * only colours that exist here are the line's own.
 */
@theme inline {
  --color-*: initial;
  --color-bg: var(--bg);
  --color-raise: var(--raise);
  --color-soft: var(--soft);
  --color-softer: var(--softer);
  --color-line: var(--line);
  --color-line-2: var(--line-2);
  --color-text: var(--text);
  --color-dim: var(--dim);
  --color-faint: var(--faint);
  --color-accent: var(--accent);
  --color-accent-2: var(--accent-2);
  --color-accent-soft: var(--accent-soft);
  --color-on-accent: var(--on-accent);
  --color-on-good: var(--on-good);
  --color-on-warn: var(--on-warn);
  --color-on-bad: var(--on-bad);
  --color-on-info: var(--on-info);
  --color-good: var(--good);
  --color-good-soft: var(--good-soft);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-bad: var(--bad);
  --color-bad-soft: var(--bad-soft);
  --color-info: var(--info);
  --color-info-soft: var(--info-soft);

  /* Kept because they are not palette choices: a hairline is `transparent`,
   * an SVG follows `currentColor`, and pure black and white are what an
   * overlay scrim and a print sheet are made of. */
  --color-transparent: transparent;
  --color-current: currentColor;
  --color-white: #fff;
  --color-black: #000;

  /*
   * Type. System stacks on purpose: a downloaded face costs a network round
   * trip before the first word appears, and the line's products are desktop
   * tools where the operating system's own face is the one the user already
   * reads everything else in.
   */
  --font-sans: 'Segoe UI Variable Text', 'Segoe UI', system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, 'Cascadia Code', 'SF Mono', Consolas, monospace;

  /*
   * Radius. Taken from what the products actually draw, not from a ratio:
   * `rounded-[9px]` appears twenty times and `rounded-[10px]` twelve, because
   * a control and the primary button were tuned by eye and then copied. The
   * scale keeps the cluster they landed in and gives it names.
   *
   * `md` is the control radius - inputs, buttons, list rows. That the primary
   * button was one pixel rounder than every other variant is not preserved:
   * the products differ from themselves there, and buttons of the same size
   * sitting side by side should not have mismatched corners.
   */
  --radius-xs: 4px;
  --radius-sm: 6px;
  --radius-md: 9px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 20px;

  /*
   * A radius nested inside another has to be smaller by the gap between them,
   * or the inner corner looks wrong against the outer one. The products did
   * this by hand once - 18px outside, 17px inside - and nowhere else.
   */
  --radius-inner: calc(var(--radius-lg) - 1px);

  /*
   * Type scale. The products live between 10px and 14px: `text-sm` and
   * `text-xs` together account for nine tenths of every size in both, and the
   * rest scattered across 9, 9.5, 10, 10.5, 11, 11.5, 12.5 and 13 - nine steps
   * inside four pixels, which no eye distinguishes and no reason justifies.
   * This is the same range with the noise removed.
   */
  --text-2xs: 10px;
  --text-2xs--line-height: 14px;
  --text-xs: 11px;
  --text-xs--line-height: 15px;
  --text-sm: 12px;
  --text-sm--line-height: 16px;
  --text-base: 14px;
  --text-base--line-height: 20px;
  --text-lg: 16px;
  --text-lg--line-height: 22px;
  --text-xl: 18px;
  --text-xl--line-height: 24px;
  --text-2xl: 21px;
  --text-2xl--line-height: 28px;

  /* Weights. `semibold` is what both products use for anything emphasised;
   * `bold` appears in neither, and the one `font-[650]` in a page title is the
   * kind of value a scale exists to absorb. */
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Tracking. The uppercase caption is the only place the products track at
   * all - and they do it at 0.08em in six files and 0.09em in three, a
   * difference nobody can see. One name settles it. */
  --tracking-caption: 0.085em;
  --tracking-tight: -0.01em;

  /* Easing. `out` for anything the user asked for - it arrives fast and
   * settles, which reads as responsive. `in-out` for something moving on its
   * own. `in` is deliberately absent: it starts slowly, which on a control
   * reads as lag. */
  --ease-out: cubic-bezier(0.2, 0, 0, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);

  /*
   * Elevation. Three steps, because the products had one and used it for a
   * toast, a dropdown and a modal alike - so a modal never sat further from
   * the page than the menu it covered.
   */
  --shadow-lift: var(--shadow-lift);
  --shadow-raise: var(--shadow-raise);
  --shadow-float: var(--shadow-float);
}

/*
 * Stacking order.
 *
 * Not in `@theme`: Tailwind has no z-index namespace, so `z-50` is a literal
 * fifty and a named step would not compile. These are custom properties a
 * component reads directly - `z-index: var(--z-modal)`.
 *
 * The order is the products' own, with the gaps closed. They ran 10 for an
 * in-flow popup, 20 sticky, 30 menu, 40 for a floating button, 50 for modals
 * and drawers, then jumped to 70 and 80 for the command palette - which had to
 * clear the modal layer and had no name to do it with.
 */
:root {
  /*
   * Motion. One duration existed before this - 160ms on a route change - and
   * everything else rode Tailwind's default. These are the steps around it:
   * `quick` for a colour or an opacity that should feel immediate, `base` for
   * something that moves, `slow` for something arriving from off-screen.
   *
   * Not in `@theme`: Tailwind's `duration-*` utility takes a literal number,
   * not a named step, so these are read directly - `transition-duration:
   * var(--duration-base)`. The easing curves opposite them ARE a namespace,
   * so `ease-out` is a class.
   *
   * Every duration here is for people who want motion: `prefers-reduced-
   * motion` cuts them to nothing further down.
   */
  --duration-quick: 120ms;
  --duration-base: 160ms;
  --duration-slow: 240ms;

  --z-popup: 10;
  --z-sticky: 20;
  --z-menu: 30;
  --z-floating: 40;
  --z-overlay: 50;
  --z-modal: 60;
  --z-palette: 70;
  --z-toast: 80;
}

/*
 * Base layer: what every product would otherwise write again. Scoped to
 * elements and to `:focus-visible`, never to a class, so nothing here can
 * collide with a component.
 */
body {
  margin: 0;
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

/*
 * In `@layer base`, so a component can turn it off.
 *
 * Unlayered, this rule has the same specificity as `focus-visible:outline-none`
 * from Tailwind - both are one pseudo-class - and wins on source order alone,
 * because the theme is imported before the utilities. Every component that
 * draws its own focus ring got this one on top of it: the command palette's
 * field had an accent outline it had explicitly opted out of, and a combobox
 * with chips drew two rings, one around the box and one around the input
 * inside it.
 *
 * A layered rule loses to any unlayered one regardless of specificity, which
 * is the whole point of cascade layers - the base layer states a default and
 * a component overrides it by saying so.
 */
@layer base {
  :focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }
}

/*
 * Scrollbars. A browser's default bar is a piece of someone else's chrome
 * sitting in the middle of the product - full width, with step arrows. These
 * are the line's own: thin, in the palette, drawn only where something
 * actually scrolls.
 */
* {
  scrollbar-width: thin;
  scrollbar-color: var(--line-2) transparent;
}

*::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

*::-webkit-scrollbar-track {
  background: transparent;
}

*::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: var(--line-2);
  background-clip: content-box;
  /* The thumb is drawn proportional to how much of the document fits on
   * screen, so a long one collapses it to a few pixels: still visible, no
   * longer catchable by a pointer. This is the floor below which it stops
   * being a control. */
  min-height: 2.5rem;
}

*::-webkit-scrollbar-thumb:hover {
  background: var(--dim);
  background-clip: content-box;
}

*::-webkit-scrollbar-corner {
  background: transparent;
}

*::-webkit-scrollbar-button {
  display: none;
}

items.docs:
Import the theme, then your product accent:

    @import './dowel/theme.css';
    @import './dowel/accents/kilna.css';

Outside the line, set the colour directly instead:

    :root { --accent-base: #2f7d6b; }

