export const buttonVariants = cva(
  [
    'inline-flex cursor-pointer items-center justify-center gap-1.5 whitespace-nowrap',
    'font-medium transition-colors',
    // Disabled is a state, not a colour: the button keeps its own hue and
    // loses contact instead, which reads the same whatever the accent is.
    'disabled:pointer-events-none disabled:opacity-50',
    '[&_svg]:shrink-0',
  ],
  {
    variants: {
      variant: {
        primary: 'rounded-md bg-accent font-semibold text-on-accent hover:bg-accent-2',
        ghost: 'rounded-md border border-line text-dim hover:border-line-2 hover:text-text',
        soft: 'rounded-md bg-accent-soft text-accent hover:bg-accent-soft/60',
        danger: 'rounded-md text-bad hover:bg-bad-soft',
        icon: 'rounded-md text-dim hover:bg-soft hover:text-text',
      },
      size: {
        sm: 'h-7 px-2.5 text-xs',
        md: 'h-9 px-3.5 text-sm',
        'icon-sm': 'size-7 [&_svg]:size-3.5',
        'icon-md': 'size-8 [&_svg]:size-4',
      },
    },
    defaultVariants: { variant: 'ghost', size: 'md' },
  },
)

export interface ButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  /**
   * Render something else with the button's clothes on - a link, most often.
   *
   * Takes the element itself rather than a boolean: `render={<a href="…" />}`.
   * A function is also accepted, for the rare case that needs the props
   * before deciding what to build with them.
   */
  render?: useRender.RenderProp
}

export function Button({ variant, size, render, className, type, ...props }: ButtonProps) {
  return useRender({
    render,
    defaultTagName: 'button',
    props: {
      // A `<button>` inside a form submits it unless told otherwise, which
      // surprises everyone once. When rendering as something else the
      // attribute is meaningless and would land on an `<a>`, so it is only
      // set for the element that has it - `render` is what says which.
      ...(render === undefined && type === undefined ? { type: 'button' } : { type }),
      className: cn(buttonVariants({ variant, size }), className),
      ...props,
    },
  })
}

/*
 * The arithmetic a calendar runs on, with no React in it.
 *
 * Split out of the Calendar because the size gate asked the right question:
 * the file was two and a half times over its ceiling, and the reason was that
 * it held two things - the sums, and the grid that draws them. These are the
 * sums, and they are what DatePicker, DateRangePicker and any product doing
 * its own date work import.
 *
 * Everything here takes and returns `YYYY-MM-DD`, and never a `Date`. A
 * birthday has no timezone; a release date has no hour. Put one in a `Date`
 * and it becomes a moment - and moments cross midnight when they are
 * serialised, which is how a date reaches a server a day early. The string is
 * what a database column holds and what JSON carries.
 *
 * `Date` appears inside, in two places only: to ask `Intl` for a name, and to
 * add days. Both are wrapped here, so no caller ever holds one.
 *
 * No date library, deliberately. `react-day-picker` is good and would bring
 * `date-fns` and `@date-fns/tz` behind it - the first heavy dependency in a
 * set that is otherwise Base UI or nothing. `Intl` already knows the part a
 * library would be consulted for: which day the week starts on here, and what
 * the months are called. The rest is the arithmetic below, and it is only
 * hard when a date is stored as a moment.
 */

/** A calendar date: `2026-09-02`. Not a moment - no time, no zone. */
export type IsoDate = string

/** Whether a string is a calendar date this component can work with, and one
 * that actually exists. `2026-02-31` parses arithmetically and is not a day. */
export function isIsoDate(value: string): value is IsoDate {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false
  const [year, month, day] = value.split('-').map(Number) as [number, number, number]
  if (month < 1 || month > 12 || day < 1) return false
  return day <= daysInMonth(year, month)
}

/** How many days that month has. The leap rule in full, because the
 * hundred-year exception is the part that gets left out. */
export function daysInMonth(year: number, month: number): number {
  if (month === 2) {
    const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0
    return leap ? 29 : 28
  }
  return [4, 6, 9, 11].includes(month) ? 30 : 31
}

/** Today, as a calendar date in the reader's own timezone.
 *
 * Deliberately not `new Date().toISOString().slice(0, 10)`, which is the
 * common spelling and is wrong: that converts to UTC first, so anyone east of
 * Greenwich late in the evening gets tomorrow. */
export function today(): IsoDate {
  const now = new Date()
  return format(now.getFullYear(), now.getMonth() + 1, now.getDate())
}

function format(year: number, month: number, day: number): IsoDate {
  return `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
}

interface Parts {
  year: number
  month: number
  day: number
}

export function parts(date: IsoDate): Parts {
  const [year, month, day] = date.split('-').map(Number) as [number, number, number]
  return { year, month, day }
}

/** The same date shifted by whole days. Goes through a `Date` at noon rather
 * than midnight: a shift over a daylight-saving boundary at midnight can land
 * on the same calendar day it started from. */
export function addDays(date: IsoDate, days: number): IsoDate {
  const { year, month, day } = parts(date)
  const moved = new Date(year, month - 1, day, 12)
  moved.setDate(moved.getDate() + days)
  return format(moved.getFullYear(), moved.getMonth() + 1, moved.getDate())
}

/** The same day-of-month in another month, clamped when it does not exist
 * there: a step back from 31 March lands on 28 February, not on 3 March. */
export function addMonths(date: IsoDate, months: number): IsoDate {
  const { year, month, day } = parts(date)
  const zero = year * 12 + (month - 1) + months
  const nextYear = Math.floor(zero / 12)
  const nextMonth = (zero % 12) + 1
  return format(nextYear, nextMonth, Math.min(day, daysInMonth(nextYear, nextMonth)))
}

/** Which weekday a date falls on, as `Intl` numbers them: 1 is Monday, 7 is
 * Sunday. `Date` numbers Sunday 0, which does not sort and does not match
 * what `getWeekInfo` returns. */
export function weekday(date: IsoDate): number {
  const { year, month, day } = parts(date)
  const js = new Date(year, month - 1, day, 12).getDay()
  return js === 0 ? 7 : js
}

/** Which day the week starts on here: 1 Monday, 7 Sunday.
 *
 * `getWeekInfo` is the current spelling and `weekInfo` the older one; some
 * engines have neither, and Monday is the majority answer worldwide. */
export function firstDayOfWeek(locale: string | undefined): number {
  try {
    const info = new Intl.Locale(locale ?? navigator.language) as Intl.Locale & {
      getWeekInfo?: () => { firstDay: number }
      weekInfo?: { firstDay: number }
    }
    return info.getWeekInfo?.().firstDay ?? info.weekInfo?.firstDay ?? 1
  } catch {
    return 1
  }
}

/** The grid of a month: whole weeks, starting on the locale's first day, with
 * the days either side included so every row has seven.
 *
 * Returned as dates rather than as numbers, so a cell never has to be told
 * which month it belongs to - it knows, and a click on a trailing day works
 * without a special case. */
export function monthGrid(month: IsoDate, locale?: string): IsoDate[][] {
  const { year, month: monthNumber } = parts(month)
  const first = format(year, monthNumber, 1)
  const start = firstDayOfWeek(locale)

  // How far back the grid starts: the distance from the first of the month
  // back to the most recent week start.
  const lead = (weekday(first) - start + 7) % 7
  const origin = addDays(first, -lead)

  const weeks: IsoDate[][] = []
  let cursor = origin
  // Six rows always, so the calendar does not change height between months -
  // a popup that resizes as you page through it is one that moves under the
  // pointer.
  for (let week = 0; week < 6; week += 1) {
    const row: IsoDate[] = []
    for (let day = 0; day < 7; day += 1) {
      row.push(cursor)
      cursor = addDays(cursor, 1)
    }
    weeks.push(row)
  }
  return weeks
}

/** The weekday initials, in the order this locale lays them out. */
export function weekdayNames(locale: string | undefined, start: number): string[] {
  const names = new Intl.DateTimeFormat(locale, { weekday: 'short' })
  // Any week works; this one begins on a Monday.
  const monday = Date.UTC(2024, 0, 1)
  return Array.from({ length: 7 }, (_, index) => {
    const offset = (start - 1 + index) % 7
    return names.format(new Date(monday + offset * 86_400_000))
  })
}

import { useMemo, useState, type KeyboardEvent } from 'react'
import { cn } from 'dowel-ui'
import {
  addDays,
  addMonths,
  firstDayOfWeek,
  monthGrid,
  parts,
  today,
  weekday,
  weekdayNames,
  type IsoDate,
} from './calendar-math'

/*
 * Calendar - a month of days.
 *
 * The sums live next door in `calendar-math`, which has no React in it; this
 * is the grid that draws them and the keyboard that moves around it.
 *
 * One tab stop for the whole grid, arrows within - the arrangement a radio
 * group has, and the reason a calendar is usable at all: forty-two tab stops
 * is not a control. Arrows move a cursor and only Enter chooses, so a product
 * listening for a change does not receive five dates on the way to the sixth.
 */

export interface CalendarProps {
  /** The selected day, or `undefined` for none. */
  value?: IsoDate
  onValueChange?: (value: IsoDate) => void
  /** Which month is shown. Uncontrolled unless given. */
  month?: IsoDate
  onMonthChange?: (month: IsoDate) => void
  /** Bounds, inclusive. A day outside them cannot be chosen. */
  min?: IsoDate
  max?: IsoDate
  /** For a range: the other end, so the days between can be shaded. */
  rangeEnd?: IsoDate
  /** Formats the names. Left alone it is the reader's own. */
  locale?: string
  /** What the grid is called, for a screen reader. */
  'aria-label'?: string
  /** Names the buttons that page the months. Required: they are icons, and an
   * icon with no name is a button that announces nothing. */
  previousMonthLabel: string
  nextMonthLabel: string
  className?: string
}

export function Calendar({
  value,
  onValueChange,
  month,
  onMonthChange,
  min,
  max,
  rangeEnd,
  locale,
  previousMonthLabel,
  nextMonthLabel,
  className,
  'aria-label': ariaLabel,
}: CalendarProps) {
  const [ownMonth, setOwnMonth] = useState<IsoDate>(() => value ?? today())
  const shown = month ?? ownMonth

  /* Which day the keyboard is on. It is not the selection: arrowing around a
   * calendar moves a cursor, and only Enter chooses - otherwise every arrow
   * key would fire `onValueChange` and a product listening for it would save
   * five dates on the way to the sixth. */
  const [focused, setFocused] = useState<IsoDate>(() => value ?? today())

  const weeks = useMemo(() => monthGrid(shown, locale), [shown, locale])
  const start = firstDayOfWeek(locale)
  const names = useMemo(() => weekdayNames(locale, start), [locale, start])
  const heading = useMemo(
    () => new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric' }).format(
      new Date(parts(shown).year, parts(shown).month - 1, 1),
    ),
    [shown, locale],
  )
  const dayNumber = useMemo(() => new Intl.DateTimeFormat(locale, { day: 'numeric' }), [locale])
  const fullDate = useMemo(
    () => new Intl.DateTimeFormat(locale, { dateStyle: 'long' }),
    [locale],
  )

  const outOfBounds = (date: IsoDate) =>
    (min !== undefined && date < min) || (max !== undefined && date > max)

  const goToMonth = (next: IsoDate) => {
    if (month === undefined) setOwnMonth(next)
    onMonthChange?.(next)
  }

  const moveFocus = (next: IsoDate) => {
    setFocused(next)
    // Paging follows the cursor: arrowing off the end of a month shows the
    // next one rather than moving to a day nobody can see.
    if (parts(next).month !== parts(shown).month || parts(next).year !== parts(shown).year) {
      goToMonth(next)
    }
  }

  const onKeyDown = (event: KeyboardEvent) => {
    const jump: Record<string, () => IsoDate> = {
      ArrowRight: () => addDays(focused, 1),
      ArrowLeft: () => addDays(focused, -1),
      ArrowDown: () => addDays(focused, 7),
      ArrowUp: () => addDays(focused, -7),
      PageDown: () => addMonths(focused, 1),
      PageUp: () => addMonths(focused, -1),
      Home: () => addDays(focused, -((weekday(focused) - start + 7) % 7)),
      End: () => addDays(focused, 6 - ((weekday(focused) - start + 7) % 7)),
    }

    const move = jump[event.key]
    if (move) {
      event.preventDefault()
      moveFocus(move())
      return
    }

    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      if (!outOfBounds(focused)) onValueChange?.(focused)
    }
  }

  const now = today()

  return (
    <div className={cn('w-64 select-none', className)}>
      <div className="mb-2 flex items-center justify-between gap-1">
        <button
          type="button"
          aria-label={previousMonthLabel}
          onClick={() => goToMonth(addMonths(shown, -1))}
          className={cn(
            'flex size-7 items-center justify-center rounded-md text-dim',
            'transition-colors hover:bg-soft hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
          )}
        >
          <svg viewBox="0 0 16 16" className="size-4" aria-hidden>
            <path
              d="M10 3L5 8l5 5"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>

        {/* The month is announced when it changes, so paging with the arrows
          * says where you have arrived rather than moving silently. */}
        <div aria-live="polite" className="text-sm font-medium text-text">
          {heading}
        </div>

        <button
          type="button"
          aria-label={nextMonthLabel}
          onClick={() => goToMonth(addMonths(shown, 1))}
          className={cn(
            'flex size-7 items-center justify-center rounded-md text-dim',
            'transition-colors hover:bg-soft hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
          )}
        >
          <svg viewBox="0 0 16 16" className="size-4" aria-hidden>
            <path
              d="M6 3l5 5-5 5"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
      </div>

      {/* One tab stop for the whole grid, and the arrows move within it - the
        * arrangement a radio group has, and the reason a calendar is usable at
        * all: forty-two tab stops is not a control. */}
      <div
        role="grid"
        aria-label={ariaLabel}
        tabIndex={0}
        onKeyDown={onKeyDown}
        className={cn(
          'rounded-md',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        )}
      >
        <div role="row" className="mb-1 grid grid-cols-7">
          {names.map((name) => (
            <div
              key={name}
              role="columnheader"
              aria-label={name}
              className="py-1 text-center text-2xs uppercase tracking-caption text-faint"
            >
              {name}
            </div>
          ))}
        </div>

        {weeks.map((week) => (
          <div role="row" key={week[0]} className="grid grid-cols-7">
            {week.map((date) => {
              const outside = parts(date).month !== parts(shown).month
              const disabled = outOfBounds(date)
              const selected =
                value !== undefined &&
                (rangeEnd === undefined
                  ? date === value
                  : date === value || date === rangeEnd)
              const inRange =
                value !== undefined && rangeEnd !== undefined && date > value && date < rangeEnd

              return (
                <div role="gridcell" key={date} aria-selected={selected || undefined}>
                  <button
                    type="button"
                    // Not a tab stop: the grid is the control. Announced with
                    // its full date, because "14" on its own is not a date.
                    tabIndex={-1}
                    disabled={disabled}
                    aria-label={fullDate.format(new Date(parts(date).year, parts(date).month - 1, parts(date).day))}
                    aria-current={date === now ? 'date' : undefined}
                    onClick={() => {
                      setFocused(date)
                      if (!disabled) onValueChange?.(date)
                    }}
                    className={cn(
                      'flex h-8 w-full items-center justify-center rounded-md text-sm tabular-nums',
                      'transition-colors',
                      outside ? 'text-faint' : 'text-text',
                      inRange && 'bg-accent-soft',
                      selected && 'bg-accent font-medium text-on-accent',
                      !selected && !disabled && 'hover:bg-soft',
                      date === now && !selected && 'font-medium text-accent',
                      date === focused && 'ring-1 ring-line-2',
                      disabled && 'cursor-not-allowed opacity-40',
                    )}
                  >
                    {dayNumber.format(new Date(parts(date).year, parts(date).month - 1, parts(date).day))}
                  </button>
                </div>
              )
            })}
          </div>
        ))}
      </div>
    </div>
  )
}

import type { HTMLAttributes, MouseEvent } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Chip.
 *
 * A badge you can act on: a filter that can be removed, a tag with a count, a
 * selected value in a field. The difference from a Badge is entirely about
 * whether something happens when you click it - and if something does, that
 * part is a real `<button>` with a real label, not a decorative cross.
 *
 * `onRemove` is the reason this exists separately. Every product wrote the
 * same removable tag and every one of them made the cross a `<span>`, which
 * the keyboard cannot reach and a screen reader does not announce.
 */
export const chipVariants = cva(
  'inline-flex items-center gap-1 rounded-full border py-0.5 pl-2.5 text-xs whitespace-nowrap transition-colors',
  {
    variants: {
      variant: {
        outline: 'border-line text-dim',
        accent: 'border-transparent bg-accent-soft text-accent',
        soft: 'border-transparent bg-soft text-dim',
      },
      /** Padding on the right depends on whether a remove button sits there. */
      removable: {
        true: 'pr-1',
        false: 'pr-2.5',
      },
    },
    defaultVariants: { variant: 'outline', removable: false },
  },
)

export interface ChipProps
  extends Omit<HTMLAttributes<HTMLSpanElement>, 'onSelect'>,
    Omit<VariantProps<typeof chipVariants>, 'removable'> {
  /** Shown after the label, for a count. */
  count?: number
}

/*
 * Removable, or not - and if removable, named.
 *
 * The two props travel together as a union rather than as two optionals, so
 * the type says what the component means: a remove button exists only when
 * there is a word for it. There is no default word on purpose. A string the
 * component invents is a string the product cannot translate, and it would
 * ship in English to every reader who does not read English.
 */
type Removable =
  | { onRemove: () => void; removeLabel: string }
  | { onRemove?: never; removeLabel?: never }

export function Chip({
  variant,
  count,
  onRemove,
  removeLabel,
  className,
  children,
  ...props
}: ChipProps & Removable) {
  return (
    <span className={cn(chipVariants({ variant, removable: Boolean(onRemove) }), className)} {...props}>
      {children}

      {count !== undefined && <span className="text-faint tabular-nums">{count}</span>}

      {onRemove && (
        <button
          type="button"
          aria-label={removeLabel}
          onClick={(event: MouseEvent<HTMLButtonElement>) => {
            // A chip is often inside something else that is also clickable.
            event.stopPropagation()
            onRemove()
          }}
          className={cn(
            'grid size-4 place-items-center rounded-full text-faint transition-colors',
            'hover:bg-line hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
          )}
        >
          <svg viewBox="0 0 16 16" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
            <path d="M4 4l8 8M12 4l-8 8" strokeLinecap="round" />
          </svg>
        </button>
      )}
    </span>
  )
}

import { useId, useState, type ReactNode } from 'react'
import { cn, lineProducts } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * ColorField.
 *
 * Picking a colour for something the product stores: a tag, a project, a
 * calendar. Note what that is *not* - it is not choosing the appearance of the
 * interface. The theme decides that, from one accent, and a field that let a
 * reader repaint the chrome would undo the argument the whole system rests on.
 *
 * So the palette comes first and the free field second. The swatches are the
 * line's own fourteen accents plus the four semantic tokens, which is the
 * vocabulary a product already speaks; a value picked there is a *name*
 * (`kilna`, `good`), not a hex, and it keeps meaning the right thing when the
 * theme changes underneath it.
 *
 * Free hex is available because the owner asked for it, and it is worth
 * saying why that does not contradict "no raw colours in components": the rule
 * is about a component hardcoding its own appearance. A colour the reader
 * chose for their own tag is the product's *data* - the same kind of thing as
 * the tag's name - and data does not come from a token vocabulary.
 *
 * The swatch is a real `<input type="radio">` per colour, in a `radiogroup`.
 * That is what makes the arrows walk the palette, what makes the choice
 * announce itself, and what makes the whole group one tab stop.
 */

/** The four semantic colours, which mean the same thing in every product. */
const SEMANTIC = ['good', 'warn', 'bad', 'info'] as const

/** Whether a string is a colour this field would accept as free input. Six
 * digits or three, with the hash - the two forms a reader actually types. */
export function isHexColor(value: string): boolean {
  return /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(value)
}

export interface ColorFieldProps {
  /** The chosen colour: a token name, or a hex string. */
  value: string
  onValueChange: (value: string) => void
  /** Whether the reader may type a colour of their own. */
  allowCustom?: boolean
  /** Names the palette for a screen reader. */
  'aria-label'?: string
  'aria-labelledby'?: string
  /** How a swatch is named. Takes the colour's name, so the product can say
   * "Lime" in its own language rather than shipping ours. */
  swatchLabel?: (name: string) => string
  /** The label on the free-entry box, when `allowCustom` is on. */
  customLabel?: ReactNode
  disabled?: boolean
  className?: string
}

export function ColorField({
  value,
  onValueChange,
  allowCustom,
  swatchLabel,
  customLabel,
  disabled,
  className,
  ...aria
}: ColorFieldProps) {
  const name = useId()
  const customId = useId()

  /* What is in the free box while it is being typed.
   *
   * It is not `value`: half of `#3fa9` is not a colour, and pushing every
   * keystroke up would either reject the reader mid-word or paint the product
   * a colour they were passing through. The box commits when what is in it is
   * a colour. */
  const [draft, setDraft] = useState(isHexColor(value) ? value : '')

  const swatches = [
    ...lineProducts.map((product) => ({ token: product.name, css: product.accent })),
    ...SEMANTIC.map((token) => ({ token, css: `var(--${token})` })),
  ]

  return (
    <div className={cn('flex flex-col gap-2', disabled && 'pointer-events-none opacity-50', className)}>
      <div role="radiogroup" {...aria} className="flex flex-wrap gap-1.5">
        {swatches.map((swatch) => {
          const chosen = value === swatch.token
          return (
            <label
              key={swatch.token}
              className={cn(
                'relative grid size-7 cursor-pointer place-items-center rounded-md border transition-colors',
                chosen ? 'border-accent' : 'border-line hover:border-dim',
                // The ring has to be on the label: the input itself is hidden,
                // so `focus-visible` on it would never be seen.
                'focus-within:outline-2 focus-within:outline-offset-1 focus-within:outline-accent',
              )}
            >
              <input
                type="radio"
                name={name}
                value={swatch.token}
                checked={chosen}
                disabled={disabled}
                onChange={() => onValueChange(swatch.token)}
                className="sr-only"
              />
              <span
                aria-hidden
                className="size-5 rounded"
                /* The one place a colour is set from a value rather than a
                 * class, because the value *is* the colour - a palette that
                 * could not show its own colours would be a list of words. */
                style={{ background: swatch.css }}
              />
              <span className="sr-only">{swatchLabel?.(swatch.token) ?? swatch.token}</span>
            </label>
          )
        })}
      </div>

      {allowCustom && (
        <div className="flex items-center gap-2">
          <label htmlFor={customId} className="text-xs text-dim">
            {customLabel}
          </label>
          <input
            id={customId}
            value={draft}
            disabled={disabled}
            /* No placeholder of its own.
             *
             * The obvious one is a specimen hex, and the lint rule that
             * forbids raw colours flags it - correctly, by the letter. Rather
             * than widen a gate that catches real violations for the sake of
             * one string, the format is shown by the monospace box and named
             * by `customLabel`, which is the product's word anyway. */
            spellCheck={false}
            onChange={(event) => {
              const next = event.target.value
              setDraft(next)
              // Committed only once it is a colour. Anything else is a word in
              // progress, and the product should not be repainted by one.
              if (isHexColor(next)) onValueChange(next)
            }}
            className={cn(fieldClasses, 'h-8 w-28 font-mono text-xs')}
          />
          <span
            aria-hidden
            className="size-5 shrink-0 rounded border border-line"
            style={{ background: isHexColor(draft) ? draft : 'transparent' }}
          />
        </div>
      )}
    </div>
  )
}

import type { Ref } from 'react'
import { Combobox as Base } from '@base-ui/react/combobox'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'
import { selectItemVariants, selectPopupVariants } from './select'

/*
 * Combobox.
 *
 * A Select you can type in. The list narrows as the query is typed, which is
 * the only difference that matters and the reason to reach for this one: a
 * Select stops being usable somewhere around thirty options, and a country
 * picker or a tag field is well past that.
 *
 * Everything the Select comment says about the native element applies here
 * too - there is no `<select>` under it, and the input is a real `<input
 * role="combobox">` so autofill, spellcheck and the phone keyboard still
 * work.
 *
 * Filtering is Base UI's: give the root an `items` array and it matches the
 * query against them with `Intl.Collator`, so accents and case behave the way
 * a reader in that language expects rather than the way `toLowerCase` does.
 * `filter` replaces the comparison; `filter={null}` turns it off for a list
 * that is filtered on a server.
 *
 * The chips are Base UI's too - Chips, Chip, ChipRemove - and that is worth
 * saying because inventing them is the obvious move and it goes wrong in one
 * specific way: hand-made chips end up as `<div>`s with an X that only a
 * pointer can reach, and the multi-select becomes keyboard-inaccessible at
 * exactly the point where it holds the most state. Base UI's are focusable,
 * walk with the arrows, and delete with Backspace.
 *
 * `Empty` renders only when nothing matched, and announces itself politely.
 * Its element stays mounted for that announcement to work, so it must not be
 * hidden with `display: none` or removed conditionally - which is why it is a
 * component here rather than a `{items.length === 0 && …}` in the product.
 */

/* Two bases, chosen by `bare`, rather than one base and an override.
 *
 * Inside `ComboboxChips` the container is the field, so the input has no
 * border, no background and no focus ring of its own - a bordered box inside a
 * bordered box reads as two controls, and two focus rings appear as one thick
 * one. The obvious way to write that is `fieldClasses` plus a few `-none`
 * classes, and it does not work: `tailwind-merge` does not treat
 * `focus-visible:outline-none` as conflicting with
 * `focus-visible:outline-2 … outline-accent`, so both survive and the later
 * one in the stylesheet wins. The same trap took `w-full` versus `w-auto`
 * earlier in this file.
 *
 * So the variant picks which set applies instead of trying to subtract from
 * one - nothing is left to a merge that has no opinion. */
export const comboboxInputVariants = cva('', {
  variants: {
    size: {
      sm: 'h-8 text-xs',
      md: 'h-9',
      lg: 'h-10 text-base',
    },
    bare: {
      true: 'h-7 w-auto min-w-24 flex-1 bg-transparent px-1 text-sm text-text placeholder:text-faint outline-none',
      false: fieldClasses,
    },
  },
  defaultVariants: { size: 'md', bare: false },
})

/** The list, and a row in it, are Select's - imported rather than copied.
 *
 * The two popups are the same object seen twice: a dropdown of options, one
 * of which can be chosen. A reader who uses both on one screen should not be
 * able to tell which is which until they type. Two `cva` calls that started
 * identical do not stay that way - one gets the padding fix - and then the
 * form has two dropdowns that are almost the same. */
export const comboboxPopupVariants = selectPopupVariants
export const comboboxItemVariants = selectItemVariants

/** The root. `items` is what gets filtered; `multiple` turns the value into an
 * array and makes the chips meaningful. */
export const Combobox = Base.Root

/** The wrapper for an input with something beside it - a clear button, an
 * icon, the chips. */
export const ComboboxInputGroup = Base.InputGroup

/** The button that opens the list without typing, for a reader who wants to
 * see everything there is. */
export const ComboboxTrigger = Base.Trigger

/** The chevron. Decorative. */
export const ComboboxIcon = Base.Icon

/** A labelled group of rows. */
export const ComboboxGroup = Base.Group

/** The rows of one group, as a render function over that group's items.
 *
 * A `List` is the listbox and there is one per combobox, so a grouped list is
 * a `List` over the groups with a `Collection` inside each - not a `List`
 * inside a `List`. Mapping by hand instead works, but the component then has
 * to be told how to match an item to a value, which is a second place for that
 * knowledge to live. */
export const ComboboxCollection = Base.Collection

/** The tick, drawn only on a chosen row. */
export const ComboboxItemIndicator = Base.ItemIndicator

/** A polite live region for the state of an asynchronous list. Stays mounted,
 * like `Empty`, so the announcement actually fires. */
export const ComboboxStatus = Base.Status

/** The container the chips sit in. Its children are plain nodes, not a render
 * function - the chosen values are mapped by `ComboboxValue` inside it.
 *
 * It wears the field's clothes and lays the chips out in a row that wraps,
 * which is the whole difference between a control and a list: unstyled, the
 * chips stack one per line and the box grows into a column of pills with the
 * input stranded underneath. The input sits on the same line as the last
 * chip and takes the rest of the width, so a half-filled field still looks
 * like a field. */
export function ComboboxChips({
  ref,
  className,
  ...props
}: Base.Chips.Props & { ref?: Ref<HTMLDivElement> }) {
  return (
    <Base.Chips
      // Taken out of `...props` and passed on deliberately: a product needs a
      // handle on this box to anchor the list to it, because the input inside
      // is only as wide as what has been typed.
      ref={ref}
      className={cn(
        fieldClasses,
        'flex min-h-9 flex-wrap items-center gap-1 py-1',
        'focus-within:outline-2 focus-within:outline-offset-0 focus-within:outline-accent',
        className,
      )}
      {...props}
    />
  )
}

/** The current value, as a render function of it. This is what turns a
 * `multiple` value into one chip per entry. */
export const ComboboxValue = Base.Value

/** `size` is taken from the native `<input size>` - a width in characters,
 * which nothing here wants - and given to the variant instead. */
export interface ComboboxInputProps
  extends Omit<Base.Input.Props, 'size'>,
    VariantProps<typeof comboboxInputVariants> {}

/** Where the query is typed. A real `<input role="combobox">`.
 *
 * Inside `ComboboxChips` it drops its own border and background: the
 * container is the field there, and a bordered input inside a bordered box
 * reads as two controls. */
export function ComboboxInput({ size, bare, className, ...props }: ComboboxInputProps) {
  // `bare` is pulled out and handed to `cva`. Left in `...props` it would be
  // spread onto the `<input>` as an unknown attribute and change nothing -
  // which is exactly what it did: the variant existed, the prop was passed,
  // and the class list came out without a trace of either.
  return <Base.Input className={cn(comboboxInputVariants({ size, bare }), className)} {...props} />
}

const iconButtonClasses = cn(
  'rounded-sm p-1 text-faint transition-colors hover:text-text',
  'focus-visible:outline-2 focus-visible:outline-accent',
  'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
)

/** Empties the value. Base UI hides it while there is nothing to clear. */
export function ComboboxClear({ className, ...props }: Base.Clear.Props) {
  return <Base.Clear className={cn(iconButtonClasses, className)} {...props} />
}

export interface ComboboxPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof comboboxPopupVariants> {
  /** Preferred side of the input. Base UI flips it when it does not fit. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. */
  align?: Base.Positioner.Props['align']
  /** Distance from the input, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /**
   * What to line the list up with. Defaults to the input that owns it.
   *
   * Pass the `ComboboxChips` box when there is one: with chips, the input is
   * only as wide as what has been typed - an empty one measured 214px inside
   * a 288px field - so a list anchored to it hangs short of the box a reader
   * sees. Base UI publishes the anchor's width as `--anchor-width`, which is
   * how the mismatch is visible from outside.
   */
  anchor?: Base.Positioner.Props['anchor']
  /** Where to portal to. Defaults to the document body. */
  container?: Base.Portal.Props['container']
}

/** The list. Portalled and positioned against the input, or the given anchor. */
export function ComboboxPopup({
  size,
  side,
  align,
  sideOffset = 4,
  anchor,
  container,
  className,
  children,
  ...props
}: ComboboxPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        anchor={anchor}
        className="[z-index:var(--z-menu)]"
      >
        <Base.Popup className={cn(comboboxPopupVariants({ size }), className)} {...props}>
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** The rows, as a list. Undressed: it is a wrapper, and the popup around it
 * already carries the border and the padding. */
export const ComboboxList = Base.List

